/bin/zsh -c "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { Schema, Either } from 'effect';
import { importManifest, manifestSchema } from './dist/index.js';
const decode = Schema.decodeUnknownEither(manifestSchema);
const parcel = { reference: ' p1 ', grams: 100, service: 'standard', extra: {} };
const input = { partner: ' shop ', parcels: [parcel, { reference: ' p2 ', grams: 200, service: 'express' }], extra: {} };
const expected = { partner: 'shop', parcels: [{ reference: 'p1', grams: 100, service: 'standard' }, { reference: 'p2', grams: 200, service: 'express' }] };
const imported = importManifest(input);
assert.deepEqual(imported, { ok: true, manifest: expected });
assert.deepEqual(decode(input).right, expected);
assert.equal(input.partner, ' shop ');
assert.equal(parcel.reference, ' p1 ');
assert.notEqual(imported.manifest, input);
assert.notEqual(imported.manifest.parcels, input.parcels);
assert.notEqual(imported.manifest.parcels[0], parcel);
const invalid = [undefined, null, true, 1, 'shop', [], {}, { partner: ' ', parcels: [parcel] }, { partner: 'shop', parcels: [] }, { partner: 'shop', parcels: [parcel, { ...parcel, reference: 'p1' }] }];
for (const field of ['reference', 'grams', 'service']) {
  const missing = { ...parcel };
  delete missing[field];
  invalid.push({ partner: 'shop', parcels: [missing] });
}
for (const grams of [undefined, null, '100', NaN, Infinity, -Infinity, 0, -1, 1.5]) invalid.push({ partner: 'shop', parcels: [{ ...parcel, grams }] });
for (const reference of ['', ' ', null, 1]) invalid.push({ partner: 'shop', parcels: [{ ...parcel, reference }] });
for (const service of ['other', '', null, 1]) invalid.push({ partner: 'shop', parcels: [{ ...parcel, service }] });
for (const value of invalid) {
  assert.deepEqual(importManifest(value), { ok: false, reason: 'invalid-manifest' });
  assert.equal(Either.isLeft(decode(value)), true);
}
console.log('Schema/importer validation, normalization, ordering, and reference isolation checks passed.');
JS"

